import{_ as t,c as s,o as i,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"周易经传集解卷十九","description":"周易经传集解 - 周易经传集解卷十九","frontmatter":{"title":"周易经传集解卷十九","description":"周易经传集解 - 周易经传集解卷十九"},"headers":[],"relativePath":"zh/classics/jingchuan-jijie/020.md","filePath":"zh/classics/jingchuan-jijie/020.md"}'),r={name:"zh/classics/jingchuan-jijie/020.md"};function c(o,a,l,d,p,h){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易经传集解卷十九",tabindex:"-1"},[n("周易经传集解卷十九 "),e("a",{class:"header-anchor",href:"#周易经传集解卷十九","aria-label":"Permalink to “周易经传集解卷十九”"},"​")],-1),e("p",null,"钦定四库全书周易经传集解家人睽卷十九 ​宋林栗撰。序：卦曰：「夷者，伤也。伤于外者必反于家，故受之以家人。」家人为卦，明夷之变也。自明夷之家人，下卦不动，上坤为巽，变其五、上二爻而成卦也。坤，顺也；巽，巽也。顺之与巽，无以相远，而成卦之才若是不同者，取其爻象而名之也。以六居五，则无以应六二；以六居上，则无以制九三，是以为明夷。变其爻，则尊卑内外莫不各当其位，是以谓为家人也。夷者，伤也。伤于外而反于家，事之必至，理之固然也。易乃取以为序，其意义安在？夫以一人之尊，而居亿兆之上，可谓崇高矣。初登于天，照于四国，可谓聪明矣。然乃夷其明而至于亡，何也？天下之本在国，国之本在家。天下之所以入于明夷者，乱之所生，未尝不始于家也。诗云：「乱匪降自天，生自妇人。」若夫伤而能悔，悔而能反者，必由家齐而后国治，国治而后天下可平。故曰：「纣以妲己亡，周以任、姒兴。」书云：「牝鸡无晨；牝鸡之晨，惟家之索。」诗云：「刑于寡妻，至于兄弟，以御于家邦。」此则伤于外必反于家，故受之以家人意也。文中子书以明内齐外言家人之象。伊川程氏曰：「万物至巽而洁齐，非巽有齐之义也。」易之取象皆如是矣，何独于「巽」而疑之？然明内齐外，不足以发指其义，伊川乃以外巽内明言其象，亦未为得。夫外巽内明，是犹明夷之义也，家人何取焉？乃若孔子，亦岂云尔哉？曰：女正位乎内，男正位乎外，而家人之象粲然著矣。由是言之，不通乎变，未可与言易也。家人：利女贞。彖曰：家人，女正位乎内，男正位乎外。男女正，天地之大义也。家人有严君焉，父母之谓也。父父，子子，兄兄，弟弟，夫夫，妇妇，而家道正，正家而天下定矣。下离上巽成卦曰「家人」者，初为「离」，二为「坎」，三又为「离」，四为「巽」。「离」，明也；「离」，丽也；「巽」，巽也；「巽」，入也。内明而外巽，内丽而外入，所以为家人者不可得而见也。「巽」，长女也；「离」，中女也。二女同居，所以为家人者不可得而见也，为其有「坎」、「离」之象焉。「坎」、「离」，男女也。合而言之，则夫妇也；重而言之，则父母也；总而言之，则一家之人也。自五以下，皆有「离」、「坎」之象焉，是以谓之家人也。然则既济之不为家人，何也？曰：「既济之终，以六居上，久而不知变，则其道穷矣，是故有濡首之象焉。若夫家人以九终之，譬如人之一家，内外皆有防闲，始终不失其严，然后家人之象成矣。」家人，利女贞，何谓也？曰：家人反复，有巽、离、兑之象焉。巽、离、兑，三女也，其在六爻为女者，二四而已。二四，阴位也，阴居之，女之正也。家人之道，利在女正也。女正则男正可知矣。或曰：「何谓也？」曰：「男子生而有四方之志，为君长则有治民之道，为臣下则有事上之宜，其所谓正，不止施于家人也。言女正，知其家道正矣。是故九五正位乎外，六二正位乎内，男女各得其正矣。五，天位也；二，地位也。天穹隆而在上，地磅礴而居下。故子曰：家人，女正位乎内，男正位乎外。男女正，天地之大义也。」或曰：「然则九三、六四，非男女之正与？」曰：「家人有夫妇之别焉，有父子之严焉，有姑妇之顺焉，有兄弟之敬焉，有娣姒之睦焉。由夫妇而言，则五，夫道也；二，妇道也，内外之位正也。由父子而言，则五为父，四为子，三为母，二为妇，上下之分定也。由兄弟而言，则五，兄也，三，弟也，二四盖娣姒也，长少之叙明也。一家之象，粲然备矣。故子曰：家人有严君焉，父母之谓也。」父父，子子，兄兄，弟弟，夫夫，妇妇，而家道正，正家而天下定矣。程氏曰：「一家之中，不严则孝敬衰，无君则法度废。」故必有所尊严而君长之者，九五、九三之谓矣。或曰：说者谓五为父，四为母，若何？曰：非也。自父母相配而言，则是夫妇也，二位是已。对子而言，故称父母。九五为父，教子以治乎外；九三为母，诏妇以治乎内。岂不坦然明白也哉？若以四言之，则母失其严，子失其顺矣。或曰：「母主乎爱，尚乎慈，系之九三，不已过乎？」曰：谚不云乎：慈母有败子，严家无格虏。昔之贤母，以教子治家名闻后世者，岂惟慈爱而已乎？子曰：「家人有严君焉，父母之谓也。」学者尚何疑焉？象曰：风自火出，「家人」。君子以言有物而行有恒。「火」者，「离」也。风者，「巽」也。火性上炎，威严之象也；风体旁行，教化之象也。火烈而风生焉，家严而化行焉。夫火，南方之物也。心，君之属也，人之所望而畏焉者也。君子观此之象，然后知身不可不正，而家不可不严矣。「言有物，行有恒」，所以修身而齐家，取「风」「火」之义也。杂卦曰：「家人，内也。」家人为卦，以男女正位而成。其在六爻，以闺门之内治为义。何者？初、上二阳，有门墙扞蔽之象；二、三、四、五，有室家男女之象焉，是以谓之内也。传曰：「君义臣行，父慈子孝，兄爱弟敬，所谓六顺也。礼：妇人送迎不出门，见兄弟不逾阈。外言不入于梱，内言不出于梱。」故家人之象，以初、上二爻为内外终始之闲，中间四爻为少长尊卑之序。初之「悔亡」，上之「终吉」，内外终始之有其闲也。二之「无攸遂」，三之「嗃嗃」，四之「富家」，五之「勿恤」，而皆系之「吉」者，长少尊卑之得其序也。或曰：然则初九以阳居刚，上九以阳居柔，其所以防闲之道不同，何也？上卦为外，下卦为内。上九者，外之极、宫之前也；初九者，内之极、室之后也。宫室之制，前有门阙，后有垣墙。门阙所以司启闭也，故刚柔杂焉；垣墙所以杜罅隙也，峻为之闲，严为之禁，岂非防微谨始之义也哉？初九：闲有家，悔亡。象曰：「闲有家」，志未变也。初九，「离」也，以阳居刚，而在一卦之下，应乎六四。四，「坎」「巽」也，故曰「闲有家」。「闲」，阑也，扞蔽之义也。有家而无闲，不能有其家者也。闲之者，礼之谓乎？所以扞蔽内外，不可窥窬者也。家人之道，外不逾阈，内不逾梱，故初九不以应言，取诸防闲以为义也，故曰「悔亡」。初应在四，是以有悔。行之于始，故得「悔亡」。人之常情，妻子之间，宠之而弗教，纵之而弗禁，其心以为爱之也。驯习浸淫，陷于不义，则长者之过也。悔而图之，将无及矣。是故君子于其始而闲之，则放僻邪侈无自而生，悔可亡也。故子曰：「闲有家，志未变也。」逮其志变习流，然后从而止之，则用力多而不可胜制矣。六二：无攸遂，在中馈，贞吉。象曰：六二之「吉」，顺以巽也。六二，坎也。以阴居柔而在下卦之中，应乎九五之「离」，故曰「无攸遂」。遂，成也，有所欲为而遂其志者也。春秋之义，大夫无遂事，而况妇人乎？六二以阴居柔，处于下而得中，位乎内而守正，无所敢成者，故曰「在中馈」。坎为酒，离为食，故有「中馈」之象。在中而主馈食，妇人之职也。礼曰：「精五饭，幕酒浆。」诗曰：「无非无仪，惟酒食是议。」以贞，斯为吉矣，故曰「贞吉」。子曰：「六二之吉，顺以巽也。」其妾妇之道欤！九三：家人嗃嗃，悔厉，吉。妇子嘻嘻，终吝。象曰：「家人嗃嗃」，未失也。「妇子嘻嘻」，失家节也。九三下体为「离」，上体亦为「离」，以阳居刚而在下卦之上，上无其应，而介于二四之间，二四皆「坎」也，故曰「家人嗃嗃」。按陆氏音义：「嗃嗃」，荀作「确确」，刘作「熇熇」；「嘻嘻」，张作「嬉嬉」，陆作「喜喜」。愚以「熇熇」、「嘻嘻」为是。今韵「嗃」字有两音：黑角切，悦乐也；黑各切，严也；并引「家人嗃嗃」为证。「熇」字有四音：虚娇切，炎气也；呼木切，热也；呼酷切，火热也；黑各切，炽也。「熇」是炎炽之貌。四音皆同。「嗃」一曰「说」，一曰「严」，未详。厥二音皆本于此文之注，盖学者相谬语，当以「熇熇」为正。「熇」，炎也；「熇熇」，炎之极也。「离」为火，故有「炎熇」之象。以阳居刚，上下皆「离」，是以谓之「熇熇」也。郑子产曰：「火烈，人望而畏之，故鲜死焉。」是火有威严之象也。家人之道，尚严而戒渎。然九三重「离」而不中，至于「熇熇」，亦云过矣，故曰「悔，厉，吉」。刚而不中，能无悔乎？伤恩则离，能无厉乎？然与其有不可制之渐，不若有不可犯之严。然则九三虽悔且厉，而家道无亏，斯为吉庆，故曰「妇子嘻嘻，终吝」。旧说以「嘻嘻」为喜笑之貌，考之爻象，不应求之辞，二音既赘且阂。诗云：「妻子好合，如鼓瑟琴。宜尔室家，乐尔妻孥。」然闺门和乐，发于喜笑，非圣人之所禁也。王氏谓：嘻，嗟叹之声。按诗「噫嘻」，礼记「嘻其甚也」，皆叹辞也。六二为妇，六四为子，二、四皆「坎」也。「坎」为加忧，故有嘻嘻愁叹之象。九三居子妇之间，处门内之长，母之象也。禀阳刚之才，体重离之象，其威赫然，望而可畏，虽过乎刚，犹未为失。若苛虐已甚，而察见渊鱼，将使之无所措其手足，而有愁叹之声，以此终之，不亦吝乎？三，下卦之极也，故有「终吝」之戒焉。子曰：「家人熇熇」，未失也；「妇子嘻嘻」，失家节也。「苦节不可贞」，其是谓乎？六四：富家，大吉。象曰：「富家大吉」，顺在位也。六四下体为「坎」，上体为「巽」，以阴居柔而在上卦之下，应乎初九，而介于九三、九五之间，三爻皆「离」也，故曰「富家大吉」。「家人」六四与六二之义同，九五与九三之义同。六二、九三既明刚柔之得其道矣，故于六四、九五互言其所未及，而推广有家之道也。「坎」为「劳卦」，「巽」为近利市三倍，故有「富家」之象。阳为富，阴为贫；阳为实，阴为虚。六四以阴居柔，而谓之「富家」，何也？曰：四，子道也。为人子者，无私货，无私畜，不敢私假，不敢私与。六四居父母之间，所应所比，莫非富贵而己独虚贫，是不富其身而富其家者也。家富而子贫，未之有也。身任其劳，家享其利，谓之「大吉」，不亦宜乎？故子曰：「富家大吉，顺在位也。」六四于家为子，于国为臣。为人子者，无以有己；为人臣者无以有己，其斯以为顺乎？九五：王假有家，勿恤，吉。象曰：「王假有家」，交相爱也。九五，「离」也。以阳居刚而在上卦之中，应乎六二而乘乎六四，二爻皆「坎」也，故曰：「王假有家」。九五刚明中正，下应六二，「离」「坎」相配，家人之极致也。然初九、九三既备其义矣，故于九五天位之爻，推广「有家」之道也。「假」，大也。「王，大有家」者，非至常人之家也，乃以天下为家者也。孝经曰：「闺门之内，具礼矣乎！严父、严兄、妻子、臣妾，犹百姓徒役也。」然则古之圣人，推一家之治，以及乎天下，如斯而已矣。故曰：「勿恤，吉。」书云：「我受命无疆惟休，亦无疆惟恤。」「恤」，忧也。「勿」者，慎之辞也。「坎」为加忧，故有「勿恤」之象。天下之治，本于一家。孝于其亲，则天下之为人子者，莫敢不孝；敬事其长，则天下之为人弟者莫敢不顺；刑于寡妻，则天下之为人夫者莫敢不义；字于厥子，则天下之为人父者莫敢不慈。差之毫厘，则缪以千里，其可以勿恤乎？诗云：「母念尔祖，聿修厥德。」与此同意。王之恤民，如其赤子；则民之爱王，如其父母，斯为吉矣。故子曰：「王假有家，交相爱也。」上九：有孚威如，终吉。象曰：「威如」之「吉」，反身之谓也。上九，「兑」也。以阳居柔，而在一卦之上，下无其应，而乘乎九五之「离」，故曰「有孚威如」也。家人六爻，自五以下，阳贞乎刚，阴贞乎柔；阳体乎「离」，阴体乎「坎」；「离」为威，「坎」为信。惟上九一爻，刚柔相济，而体乎「兑」。「兑」，说也。家人，心说而诚服者也。是以兼乎威信而言之。威无信则不立，信无威则不行。家人之终，别无他义，惟威与信不可偏废，不可暂弛，故曰「终吉」。以此终之，斯为吉矣。而夫子则释之曰：「威如之吉，反身之谓也。」孟子曰：「身不行道，不行于妻子。」古之人所以能齐其家者，言有物而行有恒也。圣人惧世俗不察，直以威严为治家之道，而不能正身以率之，则父子有相夷之恶，夫妇有反目之衅，兄弟有阋墙之丑，何威之能行哉？惟君子反求诸己，视听言、动，非礼不为，斯有不言而信，不怒而威者矣，岂徒刚猛严厉而已哉？此与大有六五「厥孚交如，威如，吉」同义。易而无备，所以为「大有」之「威」；反身而诚，所以为家人之「威」也。序卦曰：「家道穷必乖，故受之以暌。」暌者，乖也。暌之成卦，家人之反也。自家人之暌，离反居上巽，变为「兑」，上下相易而成卦也。离，火也；巽，木也；兑，泽也。木之于火，有相生之义，离体居下，有炎上之情，是以为「家人」也。大之于泽，有相畏之资，离上兑下，无相与之意，是以为「暌」也。刚柔上下，各当其位，是以为「家人」也。反则易位，是以为「暌」也。「暌」有两义：有自然之暌，有不合之暌。「二女同居，其志不同行」，此自然之暌；「家道穷必乖」，此不和之暌也。或曰：「家道穷必乖」，何谓也？曰：家人之道，以严为上。如上九之严，则终乎「吉」；如九三之严，则终乎「吝」。极炎上之性，而无逮下之情，其致乖也，不亦宜乎？暌：小事吉。彖曰：「暌」，火动而上，泽动而下。二女同居，其志不同行。说而丽乎明，柔进而上行，得中而应乎刚，是以小事吉。天地暌而其事同也，男女暌而其志通也，万物暌而其事类也。暌之时用大矣哉！下兑上离成卦曰「暌」者，初为兑，二为离，三为坎，四又为离。离，火也；兑，泽也。火动而上，泽动而下，则不交而否矣。为其有离、坎之象焉，是以不谓之「否」，而谓之「暌」也。兑，少女也；离，中女也。二女同居，其志不同行，则不和而讼矣。为其有离、坎之象焉，是以不为讼而为暌也。暌者，乖也。始乖而终合，是以谓之暌也。夫离、坎者，既济之象也。始乎暌，终乎既济，则暌之义也。「暌，小事吉」，何谓也？曰：书不云乎：「汝则从，龟从，筮从，卿士从，庶民逆，吉。汝则从，龟从，筮从，卿士逆，庶民逆，作内吉，作外凶。龟筮共违于人，用静吉，用作凶。」夫兴天下之大事，建天下之大业，是必天人和同，上下丕应而后可。所谓「朕志先定，询谋佥同，鬼神其依，龟筮恊从」是也。至于兴一利，除一害，凡所施为措注，必上下叶同，不几乎惟予言而莫予违者乎？事有利害，计有得失，兼天下之谋，合天下之虑，往往暌而不同，是故人主慎所择焉，故曰「小事吉」也。子曰：「暌，火动而上，泽动而下。二女同居，其志不同行。说而丽乎明，柔进而上行，得中而应乎刚，是以小事吉。」夫说而丽明，柔而上行，中而应刚，斯谓之合矣，而何暌之云乎？曰：天地之间，有合必有离，有聚必有散。暌本生于同，而同盖出于暌，不同则无暌，不暌则无同。今夫离火兑泽，同赋形于天地，中女少女，同鞠育于闺门，其始未尝不同也。火性炎上，泽性润下，中女丽坎，少女配艮，其后未尝不暌也。暌之为义，盖取诸此。然即其卦而求之，则「说而丽明，柔而上行，得中而应乎刚」，此则要其归，同欤？异欤？故曰：天地暌而其志同也，男女暌而其志通也，万物暌而其事类也。暌之时用大矣哉！天地之形虽分，而生成之事则同；男女之体虽异，而室家之志则通；万物之品虽殊，而孕育之事则类。自其同以求其暌，则火泽相近而异趣，二女同居而异行，是「暌」也。即其暌以求其同，则天地至于万物，虽形分体异，品类散殊，要其归，未始不同也。是故暌之六爻，皆始乖而终合。然则明目达聪，并谋兼智，百官殊职，万民异业，刑德并施，文武咸用，同归于治者，暌之义也。颜渊、季路，共出孔门，周公、召伯，夹辅王室，夫岂必尽同耶？夫惟圣人，为能收天下之暌，以成天下之用。暌之时用，斯为大矣。繋辞曰：「弦木为弧，剡木为矢，弧矢之利，以威天下，盖取诸暌。」何也？弧矢之作，暌全材以成器，合众暌以为用，则暌之象著矣。离为戈兵，兑为毁折，坎为矫揉，故有弧矢之象焉。象曰：上火下泽，「暌」；君子以同而异。「上火下泽」，暌之象也。「君子以同而异」者，论语云：「君子和而不同，周而不比，群而不党。」皆其义也。或曰：「既云和而不同，又曰同，何也？」以和与同言之，则同为小人；以同而异言之，则同为君子。或曰：「子夏传云：同其事而异其群，何谓也？」曰：「夫言岂一端而已哉？言各有当也。」临川王氏云：「同其道而异其事，二者孰得？」曰：「无害也。道同而事异者，君子之与君子也；事同而道异者，君子之与小人也。以文害辞，以辞害意者，难与言经矣。」杂卦曰：「暌，外也。」暌之为卦，以始乖终合而成。其在六爻，以内外相应为义。然「家人」谓之内，「暌」谓之外者，「家人」二女也，女正位乎内者，成家之义，故系之「长女」也。「暌」亦二女也，女志在乎外者，从人之义，故系之「少女」也。然方「暌」之初，上下乖隔，阳务上行，阴务下趋。阳上行而弗得其配，阴下趋而弗遇其主，困而后反，反而后遇，故九四、上九皆为「暌孤」，六三「掣曳」而无初也。上行下趋，虽有隔阂，不旋其踵而得之者，初九、六五皆为「悔亡」，九二「遇主」而「无咎」也。「暌」之为外，斯其旨欤？初九：悔亡。丧马勿逐，自复。见恶人，无咎。象曰：「见恶人」，以辟咎也。初九，「兑」也，以阳居刚而在下卦之下，上无其应，而九四之「离」适当其位，故曰「悔亡」。「离」为火，「兑」为泽，此彖所谓「上火下泽」者。然初九之泽居于下，下流而百谷之所钟也。四虽上行，而二、五、三之各从其配，四无所与，然后复归于初，初则受而纳之，是以谓之「悔亡」也，故「丧马勿逐，自复」。「离」为火，「马」，火畜也，阳物也。是故九四之「离」有「马」象焉。以九居初，不应于四，有「丧马勿逐」之象焉。九四上行为「离」，反下亦为「离」，进无所遇，穷于上者必反于下，故有「自复」之象焉。「丧」，失也。易言「丧牛」者，丧其顺也。「丧羊」者，丧其狠也。丧马者，丧其健也。初九之有九四，可谓健矣，而介于六三、六五之间，宜其逸而不可禁也。然方暌之时，物情乖异，九四虽欲从于三五，而不免按剑之疑。五自应二，三自应上，四无所归，其势自复，虽勿逐可也，逐则遂丧之矣。故曰：「见恶人，无咎。」忠臣不事二君，贞女不事二夫，今也背五而逃，惟利是视，行无所纳，冒耻而归，可谓恶人也。然方暌之时，臣主未定，或离或合，或叛或从，苟以为愆，何者非罪？丧而逐之，是使之不敢复也。复而不纳，是使之无所容也。恶人无所容，君子岂久安之道哉？昔之有大度者，惟能宽容慱爱，含垢纳污，来者勿拒，去者勿追，然后天下狙诈咸作吾使，又何咎之有哉？若不忘旧恶，皆雠敌也。故子曰：「见恶人以辟咎也。」晋文公归国，寺人披请见，公使人让之，且辞焉。对曰：「臣谓君之入也，其知之矣。若犹未也，又将及难。行者甚众，岂惟刑臣？」公见之，以吕、却之难告。里凫须又请见。公之出也，窃其藏以逃。公辞焉以沐。里凫须谓仆人曰：「沐则心覆，心覆则图反，宜吾不得见也。国君而雠匹夫，惧者众矣。」仆人以告，公遽见之。汉高帝先雍齿之封，赦季布之罪，推此类也，岂非「见恶人以辟咎」乎哉？九二：遇主于巷，无咎。象曰：「遇主于巷」，未失道也。九二，「离」也。以阳居柔而在下卦之中，应乎六五之「坎」，故曰「遇主于巷」。「离」为相见，五在君位，故有「遇主」之象。夫阳升而阴降者也，「离」炎上而「坎」下流也。九二、六五得中而相与者也，其后之必矣。然方「暌」之时，介于六三、九四之间，五欲从二而四阂其路，二欲从五而三阨其冲，是以相遇于巷也。「巷」者，径也。「遇」者，适相值也。相值于巷，宜若钻穴逾墙之类矣。然其所遇者，主也。不于涂而于巷者，辟寇而相求也。虽遇非其所，岂为失道哉？故曰「无咎」。而子曰：「遇主于巷，未失道。」巷虽非道，可以通乎道矣。杨子曰：「涂虽曲而通诸夏，则由诸九四之遇元夫，上九之遇雨，皆离象也。」六三，见舆曳，其牛掣，其人天且劓。无初有终。象曰：「见舆曳」，位不当也。「无初有终」，遇刚也。六三上体为「坎」，下体为「巽」，以阴居刚而在下卦之上，应乎上九之「离」，故曰：「见舆曳，其牛掣，其人天且劓。」「天」当作「而」，字之讹也。安定胡氏曰：「汉法，有罪髡其鬓发曰而。」今从之。「坎」于马为「曳」，于舆为「多眚」，于人为「加忧」、为「刑伤」。「巽」为「进退」、为「不果」，于人为「寡发」、为「广颡」，故有「曳掣」、「髡劓」之象。舆所以载也，牛所以驾也，人所以乘之也。不曰「马」而曰牛者，阴柔故也。「曳」，牵于后，谓九二也；「掣」，阻于前，谓九四也。而「髡其首」，谓上九也。「劓」，刑其面，谓九四也。六三不当其位，而介于九二、九四之间，是以有「曳掣」之患。应于上九，掣而不得进，邻于九四，噬而不肯从，是以有「髡劓」之灾也。或曰：上髡其首，四刑其面，九二独无伤耶？曰：九二应在六五，难在六三，四方噬三，则二以其间与五相遇，其肯为三不利耶？然则其曳之何也？曰：三近于二，不能自克，故有「牵曳」之象，非二之挽而留之也。或曰：自二以上，皆有离坎之体，焉知二之不从三，而三之不从四乎？曰：方暌之时，人情乖疑，虽得其主，犹未必用，虽遇其配，犹未遽合，况非其主与其配乎？是以知其不从也。故曰：无初有终。舆曳而牛掣，首髡而鼻割，可谓「无初」矣。九四噬三而不能合，然后上九说弧而纳之，是之谓「有终」也。故子曰：「见舆曳，位不当也。」无初有终，遇刚也。伊川程氏曰：「始为二阳所厄，故无初。」暌极则有终合之理，故有终。夫不正而合，未有久而不离者也。合以正道，则无终暌之理。故贤者顺理而安行，智者知几而固守。九四：暌孤，遇元夫，交孚，厉无咎。象曰：「交孚」「无咎」，志行也。九四上体为「离」，下体亦为「离」，以阳居柔而在上卦之下，下无其应，故曰「暌孤」。「暌」，乖也。「孤」，独也。九四下无其应，上行而无所遇，介于六三、六五之间，二爻皆莫之与，乖而又独，是以谓之「暌孤」。六三介于二四而谓之「掣曳」，九四介于三五而但曰「暌孤」者，三阴而四阳，三「坎」而四「离」也。九四一爻，上下皆「离」，穷于上必反于下。五既应二，三又从上，四无所与，必复于初，故曰「遇元夫，交孚」。「元」，善之长也。以九居初，于四为配，是以谓之「元夫」也。初，阳也；四，亦阳也。以阳遇阳，其谓之「元夫」，何也？阳为行，阴为止。若二阴居相应之位，各止其所，决无相从之义。今上下皆阳，各有行健之志，虽无感应相与之情，而有同气相求之理。及其「暌孤」，不约而合，是以谓之「交孚」也。故曰「厉无咎」。而子曰：「交孚无咎，志行也。」孟子言伊尹五就汤，五就桀，虽未必然，然去桀而归汤则有之。咸有一德，斯之谓与！六五：悔亡。厥宗噬肤，往何咎？象曰：「厥宗噬肤」，往有庆也。六五，「坎」也。以阴居刚，而在上卦之中，应乎九二之「离」，故曰「悔亡」。阳升而阴降，「离」上行而「坎」下趋，是以系之「悔亡」也。当「暌」之时，间于三四，是以有悔。得中而应，始乖而终合，是以「悔亡」也。故曰：「厥宗噬肤，往何咎。」「宗」，同体也，谓九四也。「肤」，柔物，谓六三也。「离」为食，「坎」为坚，「巽」为柔，故有「厥宗噬肤」之象。六三有应在上，九四扼而取之，如噬肤而难嗑也。五以其间往从九二，斯遇之矣，又何咎之有哉？故子曰：「厥宗噬肤，往有庆也。」阴阳相获，斯为庆也。或曰：「同人」二五不犹之暌乎？「同人」之二曰：「同人于宗，吝。」其五曰：「大师克遇。」而「暌」之五曰：「厥宗噬肤，往何咎？」其二曰：「遇主于巷，无咎。」何其得失难易之殊也？曰：「同人」，与人同者也，是以相遇于大师也；「暌」者，与人异者也，是以不遇诸涂而遇诸巷也。凡易之辞，岂苟云乎哉？上九：暌：孤，见豕负涂，载鬼一车，先张之弧，后说之弧。匪寇婚媾。往，遇雨则吉。象曰：「遇雨」之「吉」，群疑亡也。上九，「离」也。以阳居柔而在上卦之上，应乎六三。三，「坎」「巽」也，故曰「暌孤」。阳升而阴降，离上行而坎下趋，又有巽入之象焉。居卦之终，亢而无与，是以暌而又孤也。故曰：「见豕负涂，载鬼一车，先张之弧，后说之弧。」离为见，坎为豕，为陷，故有负涂之象；为幽，为舆，故有载鬼之象；离为戈兵，故有张弧之象。始暌而终合，故有后说之象。离也者，明也。其在上九，则炎上之极也，伤于亢而过于猜者也。当暌之时，物情乖异，六三自奋于掣曳之中，下无所与，反而从上，上九犹以猜疑之意，逆而拒之，故见豕负涂，污秽之甚也；见车载鬼，异类之甚也。是以张弧而射之。然暌极必通，疑久必解，穷于上必反于下，故五既遇二，四既遇初，六三之情不辨而彰，然后上九说其弧而纳之。三，坎也；上，离也。方其暌也，未济之象也。及其合也，既济之象也。故曰：「匪寇婚媾，往遇雨则吉。」坎为盗，故有寇象。其配在离，故有婚媾之象。阴阳交际，故有遇雨之象。夫逆而拒之，则见其为豕，怪其为鬼，疑其为寇。近而参之，则知其非寇，乃婚媾也。往而遇之，斯为吉矣。故子曰：「遇雨之吉，群疑亡也。」方其疑之也，为豕、为鬼、为寇，无所不至矣。及其遇之也，为婚媾、为云雨，皆坎象也。非前后之有殊，疑信异而美恶变矣。君臣之间，夫妇之际，可不察与？或曰：「六三有坎、巽之体而象其物，宜有坎无巽，何也？」曰：坎，上体也，巽，下体也。初辞拟之，卒成之终，至于上九，反而从其配矣。有坎而无巽，不亦宜乎！周易经传集解卷十九，",-1)])])}const _=t(r,[["render",c]]);export{m as __pageData,_ as default};
